                if (y,cc) in M: continue
                out[y][cc]=5
        out[cr][cc]=v; out[r][c]=v
    # crossings -> 4, then down-left diagonal staircase from each crossing
    for r in range(H):
        for c in range(W):
            if out[r][c]==4:
                y,x=r+1,c-1
                while 0<=y<H and 0<=x<W:
                    if out[y][x]!=5 and out[y][x]!=4: out[y][x]=4
                    y+=1; x-=1
    return out
