        cr,cc=r+dr,c+dc
        hs=(min(c,cc),max(c,cc)); vs=(min(r,cr),max(r,cr))
        segs.append(('H',r,hs[0],hs[1]))
        segs.append(('V',cc,vs[0],vs[1]))
