def f(g):
    # marker -> fixed offset -> copy; draw: H run (marker..copy), V run at copy col, copy keeps marker color
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    offs={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}
    marks=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]: marks.append((r,c))
    runs=[]
    for (r,c) in marks:
        v=g[r][c]
        cr,cc=r+offs[v]
        while cr<0: cr=-cr-1
        while cc<0: cc=-cc-1
        hs=range(min(c,cc),max(c,cc)+1)
        vs=range(min(r,cr),max(r,cr)+1)
        runs.append({'mk':(r,c),'v':v,'H':set(hs),'V':set(vs),'cr':cr,'cc':cc})
    res=[r[:] for r in g]
    out=[[0]*W for _ in range(H)]
    for s in runs:
        r_,c=s['mk']
        # horizontal run along marker's row
        for x in s['H']:
            if x!=c and out[r_][x]==0: out[r_][x]=5
        # vertical run at copy column, spanning marker row..copy row
        for y in s['V']:
            if out[y][s['cc']]==0: out[y][s['cc']]=5
        # copy cell: keep marker color
        out[s['cr']][s['cc']]=s['v']
    # crossings: cells on H of one marker AND V of another -> 4 + down-left diagonal
    for i,a in enumerate(runs):
        for b in runs[i+1:]:
            common=a['H']&b['V']
            for x in common:
                y=a['mk'][0]
                key=(y,x)
                if res[key[0]][key[1]]!=4 and key not in {(y,x) for y,x in []} and True:
                    pass
                if res[y][x]!=4:
                    res[y][x]=4
                    yy,xx=y+1,x-1
                    while 0<=yy<H and 0<=xx<W and res[yy][xx]==0:
                        res[yy][xx]=4
                        yy+=1; xx-=1
    return res
