    src=[r[:] for r in g]; H=len(g); W=len(g[0])
    offs={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}
    marks=[]; mkset=set()
    for r in range(H):
        for c in range(W):
            if src[r][c]: marks.append((r,c)); mkset.add((r,c))
    copies=set()
    for (r,c) in marks:
        v=src[r][c]
        cr,cc=(r+offs[v][0])%H,(c+offs[v][1])%W
        copies.add((cr,cc))
        runs=[]  # placeholder - redo cleanly below
    runs=[]
    for (r,c) in marks:
        v=src[r][c]
        cr,cc=(r+offs[v][0])%H,(c+offs[v][1])%W
        hi=set(range(min(c,cc),max(c,cc)+1))
        vi=set(range(min(r,cr),max(r,cr)+1))
        runs.append(dict(mk=(r,c),v=v,H=hi,V=vi,cr=cr,cc=cc))
    res=[row[:] for row in src]
    painted=set()
    for s in runs:
        for x in s['H']: res[s['mk'][0]][x]=5
        for y in s['V']: res[y][s['cc']]=5
        res[s['mk'][0]][s['mk'][1]]=s['v']
        cp=(s['cr'],s['cc'])
        if cp not in mkset: res[cp[0]][cp[1]]=s['v']
    def trycross(a,b):
        y,x=a['mk'][0],b['cc']
        if (y,x) in mkset or (y,x) in copies: return None
        if res[y][x]!=5: return None
        return (y,x)
    for i,a in enumerate(runs):
        for j,b in enumerate(runs[i+1:],i+1):
            pt=trycross(a,b) or trycross(b,a)
            if pt:
                y,x=pt; painted.add(pt); res[y][x]=4
                yy,xx=y+1,x-1
                while 0<=yy<H and 0<=xx<W and res[yy][xx]==0:
                    res[yy][xx]=4; painted.add((yy,xx)); yy+=1; xx-=1
    return res

